import React, { useState } from "react";

function Login() {
  const [isLogin, setIsLogin] = useState(true);

  const [form, setForm] = useState({
    name: "",
    email: "",
    password: "",
  });

  const handleSubmit = (e) => {
    e.preventDefault();

    if (isLogin) {
      // LOGIN
      const user = {
        name: "Mithilesh",
        email: form.email,
        role: "USER",
        token: "dummy-token",
      };

      localStorage.setItem("user", JSON.stringify(user));
      alert("Login Successful");
    } else {
      // REGISTER
      alert("Registered Successfully (Dummy)");
      setIsLogin(true); // switch to login after signup
    }
  };

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        {/* Toggle Buttons */}
        <div style={styles.toggle}>
          <button
            style={isLogin ? styles.activeTab : styles.tab}
            onClick={() => setIsLogin(true)}
          >
            Sign In
          </button>
          <button
            style={!isLogin ? styles.activeTab : styles.tab}
            onClick={() => setIsLogin(false)}
          >
            Sign Up
          </button>
        </div>

        <form onSubmit={handleSubmit} style={styles.form}>
          {/* Show name only in signup */}
          {!isLogin && (
            <input
              placeholder="Name"
              onChange={(e) =>
                setForm({ ...form, name: e.target.value })
              }
            />
          )}

          <input
            placeholder="Email"
            onChange={(e) =>
              setForm({ ...form, email: e.target.value })
            }
          />

          <input
            type="password"
            placeholder="Password"
            onChange={(e) =>
              setForm({ ...form, password: e.target.value })
            }
          />

          <button style={styles.submitBtn}>
            {isLogin ? "Login" : "Register"}
          </button>
        </form>
      </div>
    </div>
  );
}

const styles = {
  container: {
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    height: "80vh",
  },
  card: {
    width: "300px",
    padding: "20px",
    borderRadius: "10px",
    boxShadow: "0 4px 10px rgba(0,0,0,0.1)",
    background: "#fff",
  },
  toggle: {
    display: "flex",
    marginBottom: "15px",
  },
  tab: {
    flex: 1,
    padding: "8px",
    border: "none",
    background: "#eee",
    cursor: "pointer",
  },
  activeTab: {
    flex: 1,
    padding: "8px",
    border: "none",
    background: "#1976d2",
    color: "#fff",
    cursor: "pointer",
  },
  form: {
    display: "flex",
    flexDirection: "column",
    gap: "10px",
  },
  submitBtn: {
    marginTop: "10px",
    padding: "8px",
    background: "#1976d2",
    color: "#fff",
    border: "none",
    cursor: "pointer",
    borderRadius: "5px",
  },
};

export default Login;
